export const enUprightFocus: Record<EnUprightFocusId, Record<string, string>> =
  Object.fromEntries(
    EN_UPRIGHT_FOCUS_IDS.map((focus) => [
      focus,
      Object.fromEntries(cards.map((card) => [card.slug, UPRIGHT_BY_CARD[card.slug][focus]])),
    ]),
  ) as Record<EnUprightFocusId, Record<string, string>>;

export const enUprightPositions: Record<
  string,
  Record<EnUprightPositionId, string>
> = Object.fromEntries(
  cards.map((card) => [
    card.slug,
    Object.fromEntries(
      EN_UPRIGHT_POSITION_IDS.map((position) => [
        position,
        UPRIGHT_BY_CARD[card.slug][position],
      ]),
    ),
  ]),
) as Record<string, Record<EnUprightPositionId, string>>;

export function enUprightFocusParagraphOf(
  focus: string,
  slug: string,
): string | null {
  if (!EN_UPRIGHT_FOCUS_IDS.includes(focus as EnUprightFocusId)) return null;
  return enUprightFocus[focus as EnUprightFocusId][slug] ?? null;
}

export function enUprightPositionParagraphOf(
  position: EnUprightPositionId,
  slug: string,
): string | null {
  return enUprightPositions[slug]?.[position] ?? null;
}
